begin
  if to_regclass('public.catalog_file_commercial') is null then raise exception 'catalog_file_commercial is not installed'; end if;
  if exists (select 1 from public.catalog_file_commercial where manufacturer = 'ohio-medical' and identity_sha256 = 'fae2607479d63ed9dc535a9609248393a902765edbc8c022ed6fec457d177360' and rows_sha256 <> '34e222a4575086a20bc3a4d0b26e081f7a7752c250ce83a2a1e6e0fb74580ae0') then
